oxy_webhelp_navlinks = {"legal_hold_snapshot_rtn-d39307e7801":{"topics":[{"title":"Legal hold limitations","shortdesc":"<p class=\"shortdesc\">Legal hold in <span class=\"ph\">RSC<\/span>, does not support certain workloads, and legal hold         status does not carry over between source and target Rubrik clusters.<\/p>","href":"saas\/legal_hold_limitations.html","attributes":{"data-id":"legal_hold_limitations"},"menu":{"hasChildren":false},"tocID":"legal_hold_limitations-d39307e7812","topics":[]},{"title":"Placing a legal hold on a snapshot","shortdesc":"<p class=\"shortdesc\">Placing a legal hold on a snapshot indefinitely retains that snapshot.<\/p>","href":"saas\/placing_legal_hold_snapshot.html","attributes":{"data-id":"placing_legal_hold_snapshot"},"menu":{"hasChildren":false},"tocID":"placing_legal_hold_snapshot-d39307e7826","topics":[]},{"title":"Removing a legal hold from a snapshot","shortdesc":"<p class=\"shortdesc\">Remove a legal hold from a snapshot to return to normal retention management for that         snapshot.<\/p>","href":"saas\/removing_snapshot_legal_hold.html","attributes":{"data-id":"removing_snapshot_legal_hold"},"menu":{"hasChildren":false},"tocID":"removing_snapshot_legal_hold-d39307e7837","topics":[]},{"title":"Legal hold for <span class=\"ph\">RSC<\/span> workloads","shortdesc":"<p class=\"shortdesc\">Legal hold preserves cloud-native and SaaS snapshots indefinitely, overriding SLA         Domain expiration to meet legal and compliance requirements.<\/p>","href":"saas\/legal_hold_workloads.html","attributes":{"data-id":"legal_hold_workloads"},"menu":{"hasChildren":false},"tocID":"legal_hold_workloads-d39307e7848","next":"legal_hold_workloads-d39307e7848"}]}};